    aliasEn: "Ultramarine · natural ultramarine · from lapis lazuli",
    histZh: "名字来自拉丁语 ultramarinus，「来自海的那一边」。颜料从阿富汗的萨里桑矿场出发，走陆路运到威尼斯，再由意大利商人分销全欧洲。文艺复兴时期它是画家里最贵的颜色，价格有时高过同等重量的黄金 —— 赞助人和画家签的合同里会专门为它单列一条，记录领用了几两、还剩多少。因为贵，它被默认留给最重要的地方：圣母的袍子。1826 年法国人吉梅用高岭土、硫磺和苏打烧出了人工群青，价格一落千丈，这种蓝才从奢侈品变成日常颜料。",
    histEn: "The name comes from the Latin ultramarinus, meaning beyond the sea: the pigment travelled overland from the Sar-e-Sang mines of Afghanistan to Venice, and Italian traders distributed it across Europe. In the Renaissance it was the most expensive colour a painter could buy, at times valued above its weight in gold. Contracts and account books list it as a separate line item, recording how much was issued and how much was returned. Because it cost so much it was reserved for the most important passages, above all the robes of the Virgin. In 1826 the Frenchman Jean-Baptiste Guimet fired kaolin, sulfur and soda into synthetic ultramarine, the price collapsed, and the colour became ordinary.",
    funZh: "天然群青和人工群青在画家眼里是两个东西，分得很清。有记载说，一些画家宁可反复调整别的颜色，也不肯用群青去铺底，只在最后一两道罩染才舍得用它；而手里有天然群青的画家，会把它当作一笔资产写进遗嘱。",
    funEn: "Painters treated natural and synthetic ultramarine as two different pigments and kept them strictly apart. Some would labour over every other colour rather than spend ultramarine on an underpainting, saving it for the final glazes; painters who owned a stock of the natural pigment sometimes listed it in their wills, like an asset.",
