    histZh: "从骨螺鳃下腺的分泌物里取得。常被引用的数字是：一克染料要上万只螺，而挤出来的黏液起初是白的，得靠日光氧化才慢慢转成紫。于是它在地中海世界几乎等同于权力本身 —— 罗马共和国有法律限定哪些等级的人才能穿，帝国时期更变成皇帝的垄断。制作过程的恶臭同样出名，染色工坊只能设在城外，否则城里人受不了。",
    histEn: "It was extracted from the hypobranchial gland of murex sea snails. The figure usually quoted is that a single gram of dye took thousands of snails, and the secretion comes out white: only sunlight and air oxidise it into purple. Small wonder it came to mean power itself in the Mediterranean world. Republican Rome passed laws restricting who was allowed to wear it, and under the emperors it became a monopoly. The process stank so badly that dye works had to be sited outside the city walls.",
    funZh: "「皇家紫」这个词比染料活得久。骨螺紫会随光线和年份继续变化，从紫红一路走到暗棕，所以古代文献描述它时彼此矛盾：有人说像凝住的血，有人说是发黑的绛。今天波斯湾一带仍有人用古法染色，染出的布要先晒，颜色才慢慢出来。",
    funEn: "The phrase royal purple outlived the snails by two thousand years. Murex purple keeps shifting with light and age, travelling from a purplish red toward a dark brown, which is why ancient writers describe it in contradictory terms: clotted blood in one account, a blackened crimson in another. Traditional dyeing with murex still continues around the Persian Gulf, and the cloth is hung in the sun before the colour appears.",
