    histZh: "把石英砂、石灰、铜（比如青铜屑）和碱一起烧到 900 度左右，得到一种硅酸铜钙晶体。这是目前已知人类第一次不靠天然矿物、自己造出来的颜料，比普鲁士蓝早四千多年。到公元前四世纪它已经横跨地中海，罗马人也在用；之后配方渐渐失传。十九世纪有人从庞贝的壁画上取下一小块重新分析成分，才把做法补回来 —— 现在实验室能按古法烧出它。",
    histEn: "Grind quartz sand, lime, a copper source such as bronze filings and an alkali together, fire them at around 900 degrees, and you get a calcium copper silicate crystal. It is the earliest pigment humans are known to have made rather than dug up, more than four thousand years before Prussian blue. By the fourth century BCE it had spread across the Mediterranean and the Romans were using it; the recipe then faded out of knowledge. Only in the nineteenth century, when a fragment was taken from a wall painting at Pompeii and analysed, was the method pieced back together. Laboratories can now fire it again.",
    funZh: "2000 年代之后的红外成像研究发现，埃及蓝在红外光下会强烈发光。于是它有了新工作：研究者用它去找那些肉眼已经褪掉的古迹彩绘 —— 帕特农神庙的雕饰、罗马图拉真广场的残件上，靠这点余晖找回了看不见的纹样。一个三千年前的颜料，成了现在的检测工具。",
    funEn: "Infrared imaging work since the 2000s found that Egyptian blue luminesces strongly under infrared light, which gave the pigment a new job: researchers use it to recover decoration that has faded beyond the visible. On the sculptures of the Parthenon and fragments from Trajan's Forum in Rome, that faint glow has revealed patterns no eye can see. A pigment three thousand years old now works as a detection tool.",
    catZh: "西方历史颜料",
