    histZh: "硫化汞。天然产出的叫辰砂，加热汞与硫也能人工合成。它是古代世界最鲜明的一种红：中国人拿它做漆器、印泥、颜料，也拿它炼丹；罗马人在凯旋式上给胜利者涂红脸，用的也是它。因为太醒目，它几乎在所有文明里都被安排在最重要的位置 —— 朱批、朱门、朱印、朱笔。代价是汞：长期接触的工匠会掉发、手抖、性情大变。",
    histEn: "Mercury sulfide, found naturally as cinnabar and also made by heating mercury with sulfur. It was the most brilliant red the ancient world had. The Chinese used it for lacquer, seal paste and painting, and also for alchemy; Romans painted the face of a triumphing general with it. Precisely because it shouts, nearly every civilisation put it in the most important place: imperial rescripts, red gates, seal ink, the marking brush. The price was mercury. Workers exposed to it over years lost their hair, developed tremors and changed in temper.",
    funZh: "中国的炼金术士长期相信朱砂里藏着长生与黄金的秘密。加热朱砂会析出水银，水银再与硫反应又变回朱砂，这个循环被读成「死而复生」。秦始皇陵里灌了大量水银，历代方士炼的丹多数含汞，唐代有几位皇帝的死与丹药有关。朱砂在道教里因此同时是仙药和毒物。",
    funEn: "Chinese alchemists long believed cinnabar held the secret of immortality and of gold. Heat it and mercury comes off; let the mercury meet sulfur again and it returns to cinnabar. That cycle was read as death and rebirth. Qin Shi Huang's tomb was filled with mercury, the elixirs of later centuries were mostly mercury compounds, and several Tang emperors died in ways their courts connected to those pills. In Daoist practice cinnabar was at once the medicine of immortality and the poison.",
