    histEn: "The method is startlingly old: hang strips of lead over a pot of vinegar, let the fumes corrode the metal, and scrape off the white powder that forms. It covers well, dries fast and behaves beautifully in oil, so from ancient Greece to the twentieth century nearly every oil painting has lead white somewhere, as ground or as highlight. Europeans were even harder on it as cosmetics. Elizabeth I covered her face and neck with a preparation of lead white and vinegar, because to be white was to be wealthy.",
    funZh: "代价是铅。画家和粉刷匠手抖、腹痛，牙龈上出现一条蓝线；长期涂脸的贵族在慢性中毒。二十世纪它被钛白和锌白取代，但铅白的化学性质也救了它自己：它变黑是因为生成硫化铅，用过氧化氢处理可以变回白色 —— 所以有些被熏黑的古画确实被「洗」回来过。",
