    histZh: "十七世纪起从印度输入欧洲，是一种透明、带一点荧光的暖黄，透纳和十九世纪风景画家很爱用。长期流传的说法是：用只喂芒果叶的牛，取它的尿，熬干成饼。1883 年的一份报告把它写成虐待动物的产物，1908 年印度禁止了这个做法，颜料随之断供，欧洲画家只好改用别的黄。",
