    histZh: "1706 年前后，在柏林的颜料工迪斯巴赫做红色颜料时，原料被含血的动物性杂质污染，结果沉出一片意料之外的深蓝。他把它卖了出去，配方随后传开 —— 这是第一个既不是从矿物、也不是从植物里来，而是被人做出来的稳定颜料：便宜、耐光、着色力强。它先是改变了绘画，后来又改变了别的：以铁盐感光的「蓝图」成了工程图纸的代称，那条蓝线一直用到现在。",
    histEn: "Around 1706 in Berlin, the colourmaker Johann Jacob Diesbach was working up a red when his materials were contaminated with an animal substance containing blood, and an unexpected deep blue precipitated out. He sold it, the recipe spread, and it became the first stable pigment that came neither from a mineral nor a plant but from a workshop: cheap, lightfast and strong. It changed painting first and other things later. Iron-based blueprinting gave engineering drawings their name, and that blue line is still in use.",
    funZh: "浮世绘的蓝也是它。葛饰北斋画《神奈川冲浪里》用的普鲁士蓝，是当时刚经由长崎进入日本的进口颜料；因为它便宜又不易褪色，浮世绘才第一次能画出一整片有层次的天空与海。它还有第二种身份：在医学上，普鲁士蓝是铊中毒和放射性铯中毒的解毒剂，靠它在肠道里把金属离子锁住带走。",
