    swEn: "chromium oxide",
    aliasZh: "铬绿 · 氧化铬绿",
    aliasEn: "Chrome green · chromium oxide",
    histZh: "铬绿一般指氧化铬绿，19 世纪前期出现，是少数几种既耐高温、又耐酸碱、还完全不透明的绿。它不太适合直接当颜料正色，因为颜色闷、发灰，但它极稳定，所以在陶瓷釉料、防锈漆和需要长期暴露的场合里一直有用。屏幕上的值是近似值，真颜料更偏橄榄。",
    histEn: "Chrome green usually means chromium oxide green, introduced in the early nineteenth century and one of the few greens that is simultaneously heat-resistant, acid-resistant, alkali-resistant and completely opaque. It is not well suited to being a principal colour, being dull and greyish, but its stability keeps it in ceramic glazes, anti-rust paints and any application exposed to the long term. The value shown is an approximation; the real pigment is more olive.",
    funZh: "氧化铬绿在钞票和邮票的印刷里地位很高 —— 因为它难仿，扫描打印时这个绿经常偏得离谱。所以今天很多钞票上还留着大块的绿，跟「钱是绿的」这个传统有关系，也跟防伪有关系。",
    funEn: "Chromium oxide green has a standing in banknote and stamp printing because it imitates badly: scanners and printers routinely misread it. That is why so many notes still carry large green areas, a matter both of the old association between money and green and of simple anti-counterfeiting.",
    catZh: "西方历史颜料",
    catEn: "Historical Pigments"
