    aliasEn: "Yan zhi · rouge · lip and cheek colour",
    histZh: "用红蓝花取红，或以茜草、紫铆合制而成，是古代女子的面脂与口脂。《齐民要术》里记了从红蓝花里「杀花」取红的做法：先捣、再淘，用酸浆或草木灰水处理，把黄色素洗掉，只留红。工序繁，好的胭脂不便宜。",
    histEn: "Made from safflower, or from madder and sappanwood together, it was the face and lip colour of Chinese women. The sixth-century agricultural manual Qimin Yaoshu records how to strip the red out of safflower: pound it, wash it, treat it with sour liquid or ash water to remove the yellow, and keep only the red. The process is laborious, and good rouge was not cheap.",
    funZh: "「胭脂」这个词的来源有两说：一说来自西域的燕支山，那里盛产红蓝花；一说来自匈奴单于正妻的称号「阏氏」，读音与胭脂相近。两种说法指向同一个方向 —— 红蓝花与这套妆容，是从北方和西域传进中原的。",
    funEn: "Two explanations are given for the word. One traces it to Mount Yanzhi in the western regions, where safflower grew in quantity; the other to the title of the Xiongnu chieftain's senior wife, pronounced almost the same. Both point one way: the flower and the cosmetics made from it came into the central plains from the north and the west.",
    catZh: "中国传统色",
