    aliasEn: "Gamboge · the yellow of Chinese painting · a tree resin",
    histZh: "从藤黄科树木树干上的切口流出树脂，凝成管状或块状，运到画室后再加水或加胶研磨使用。这种树主要长在东南亚，古代靠海路输入，所以国画家手里那一块藤黄是进口货，价格不低，用的时候要现磨。它明亮、透明，中国传统绘画里用来画花叶，常和花青、墨配合。它同时是一味中药，但有大毒，用量必须极小心。",
    histEn: "The resin runs from cuts made in the trunk of trees in the garcinia family and hardens into sticks or lumps, which the studio then grinds with water or glue. Bright and transparent, it was used in Chinese painting for flowers and leaves, usually alongside indigo blue or ink. It is also a medicine in the Chinese pharmacopoeia, but a highly toxic one, and doses had to be watched closely.",
    funZh: "国画里常把藤黄和墨配在一起 —— 两者相调格外醒目，因此在旧时也被当作危险警示的配色。藤黄还有个麻烦：耐光性一般，长期见光的画上它会变淡。修复古画时，往往能在一幅画里看出哪一部分先「退」了。",
    funEn: "Gamboge and ink are often paired in Chinese painting because together they are extremely striking, which is also why the combination was used for hazard warnings. Its weakness is lightfastness: it fades on paintings that see the sun, and conservators can often read off a picture which passages went first.",
