    aliasEn: "Shi qing · mineral blue · a companion of malachite",
    histZh: "由蓝铜矿研磨而成，是传统中国画里最正的蓝。它和石绿（孔雀石）常常在同一矿脉里伴生，一蓝一绿，性相近，古人用它们画山石与树叶。敦煌壁画里的青绿主要就是这两种矿物颜料：矿物色颗粒粗、遮盖强、千年不褪，所以今天的壁画上蓝和绿还亮着，而植物色的红早就淡了。",
    histEn: "Ground from azurite, it is the truest blue in traditional Chinese painting. It occurs with malachite in the same ore bodies, one blue and one green and close in nature, and the two were used together for rocks and foliage. The blues and greens of the Dunhuang murals are largely these two mineral pigments: coarse, opaque and stable, so the blue and green are still bright today while the plant-based reds faded centuries ago.",
    funZh: "石青按颗粒粗细分等级：头青最粗最亮，用来铺大面；越细的二青、三青越灰，适合罩染。价格也按级走，头青最贵。所以一幅青绿山水里哪块用头青、哪块用三青，本身就透露了这幅画的成本。",
    funEn: "Azurite was graded by particle size. The coarsest and brightest, head blue, was for large areas; the finer grades were greyer and suited to glazing, and the price fell with the grade. Which passages in a blue-and-green landscape got the top grade and which got the cheap one tells you what the painting cost.",
