    swEn: "Since 1905",
    aliasZh: "吉百利紫 · Cadbury Purple · 深度紫",
    aliasEn: "Cadbury purple · a deep royal purple",
    histZh: "吉百利从二十世纪初开始把紫色用在自己的包装上，据说这一选择与维多利亚时代认为紫色象征尊贵有关。一百多年下来，紫色包装、紫色招牌、紫色工服都成了这家英国巧克力公司的标识。2004 年它申请把这一种紫注册成商标，竞争对手随即提出异议，之后在英国和欧盟拉锯了近十年。",
    histEn: "Cadbury began using purple on its packaging in the early twentieth century, reportedly because the Victorian era treated purple as the colour of distinction. Over a hundred years the purple wrappers, signage and uniforms became the mark of the British chocolate firm. In 2004 it applied to register that particular purple as a trademark; competitors objected, and the dispute ran on in the UK and the EU for nearly a decade.",
    funZh: "这类案子的争点往往特别细：要注册的不是「紫色」，而是某一种紫在某一类商品上的使用。法庭要判断的是这个色有没有在消费者心里和一家公司绑定，以及保护它会不会把别人逼得没颜色可用 —— 后一条往往是竞争对手最主要的抗辩理由。",
    funEn: "The fighting in these cases is extremely specific. What is being registered is never purple, but one particular purple on one class of goods. The court has to decide whether that shade has become attached to one company in consumers' minds, and whether protecting it would squeeze competitors out of usable colours, which is usually the main line of objection.",
