    histZh: "星巴克 1971 年创立时用的是棕色，强调咖啡豆的产地与烘焙；1987 年被收购后换成了绿色系的标志，此后绿色一路加深、越来越稳。到 2011 年四十周年时，标志上的「Starbucks Coffee」字样被整个去掉，只剩那条双尾美人鱼和一个绿底 —— 品牌判断自己已经不需要用文字说明自己是谁了。",
    histEn: "Starbucks opened in 1971 with a brown logo that underlined beans and roasting. After the 1987 acquisition it moved to green, and the green deepened and settled over the following decades. For the fortieth anniversary in 2011 the words Starbucks Coffee were removed altogether, leaving the twin-tailed siren on a green ground: the company judged that it no longer needed to spell out who it was.",
    funZh: "那次改版在品牌设计里被反复引用，因为它是「减少」而不是「增加」：去掉文字、去掉外圈、去掉一种颜色。用颜色承担全部识别功能的代价是它必须极其稳定 —— 你今天见到的那个绿，在两万多家门店、几十个国家的印刷条件下都得是同一种绿。",
