    aliasZh: "法拉利红 · Rosso Corsa · 「赛车红」",
    aliasEn: "Rosso corsa · racing red",
    histZh: "二十世纪早期，国际赛车组织按参赛国的国籍分配车身颜色：意大利红、法国蓝、英国绿（就是后来「英国赛车绿」的来源）、德国银。红是意大利的，所有意大利车队都涂红，法拉利只是其中最出名的一家。战后这套国籍配色制度废除了，但红色留了下来 —— 因为它在电视上太显眼。",
    histEn: "In the early twentieth century the international racing body assigned car colours by the nationality of the entrant: red for Italy, blue for France, green for Britain (which is where British racing green comes from), silver for Germany. Red belonged to Italy and every Italian team painted it on; Ferrari was simply the most famous of them. The nationality system was dropped after the war, but the red stayed, because on television it is impossible to miss.",
    funZh: "1960 年代恩佐·法拉利曾把「法拉利红」短暂让给一家美国车队使用，后来收回；此后这个红基本只属于法拉利。它常被当作「颜色本身就是品牌」的典型：在赛道上你不需要看标志，只要看见那个红，就知道是谁。",
    funEn: "In the 1960s Enzo Ferrari briefly allowed an American team to race in Ferrari red before withdrawing the permission, and since then the red has belonged essentially to one marque. It is the standard example of a colour that is itself the brand: on a track you do not need to read a badge, you only need to see that red.",
    catZh: "品牌与命名色",
    catEn: "Brand & Named"
