    aliasZh: "震撼粉 · Shocking Pink · 亮得发烫的品红",
    aliasEn: "Shocking pink · the loudest magenta",
    histZh: "1937 年，意大利设计师艾尔莎·夏帕瑞丽把这个颜色放进她的高级定制系列，并给它取名「震撼粉」。在这之前，粉红在服装里一直是柔和、温和的一档 —— 夏帕瑞丽偏要用一种亮到发烫的品红，把它改成有攻击性的颜色。这个转变后来被服装史反复讨论：颜色的性别含义并不是天生的，是被用出来的。",
    histEn: "In 1937 the Italian designer Elsa Schiaparelli put this colour into her couture collection and named it shocking pink. Until then pink in dress had sat in the soft and gentle register; she insisted on a magenta bright enough to burn, and made it aggressive. Fashion history has chewed over the shift ever since: the gendered meaning of a colour is not innate, it is built by use.",
    funZh: "关于「震撼」这个名字有个流传的说法：她是从卡地亚一颗巨型粉色钻石的颜色里取的灵感 —— 那颗钻石在 1930 年代上过报纸。无论出处如何，包装、香水瓶、指甲油、甚至装杂志的纸袋都用了这个粉，一个颜色就这么被做成了文化事件。",
    funEn: "The name is said to have come from a huge pink diamond that Cartier had handled, which was in the papers in the 1930s. Whatever its origin, the pink went onto packaging, perfume bottles, nail polish and even the paper bags the magazines came in, and a colour became a cultural event.",
