    swZh: "四色体系之一",
    swEn: "one of four",
    aliasZh: "谷歌红 · Google Red",
    aliasEn: "Google red",
    histZh: "谷歌红是四色体系里负责「G」的那一个。它比正红偏橙、偏亮，在白色背景上足够跳，在深色界面上也不至于糊掉。这类红有个共同的设计约束：必须同时能当强调色和警示色用，所以不能太暗发闷，也不能太粉显得软。屏幕上的值是官方规格的近似值。",
    histEn: "Google red carries the G in the four-colour set. Warmer and brighter than a true red, it stands out adequately on white and does not muddy on a dark interface. Reds in this role share a design constraint: they must serve as both accent and warning, so they can be neither so dark as to look dull nor so pink as to look soft. The value shown approximates the published specification.",
    funZh: "品牌红和交通红是两回事：品牌红要考虑在深色模式下的表现，不能太暗；而交通标志的红追求的是远距离识别，通常更深更纯。同一个色相，两种用途，取舍点完全不同。",
    funEn: "A brand red and a traffic red are different problems. The brand version has to work in dark mode and therefore cannot go too deep, while signage red optimises for recognition at distance and is typically darker and purer. One hue, two jobs, opposite compromises.",
