    histZh: "谷歌黄是四色里明度最高的一个，负责第二个「o」。黄色在屏幕上是最难处理的色相之一：在白底上容易显得发飘，在深底上又容易刺眼。所以品牌黄通常会被压一点饱和、往橙的方向偏，换取稳定性。屏幕上的值是官方规格的近似值。",
    histEn: "Google yellow is the lightest of the four and carries the second O. Yellow is among the hardest hues to manage on screen: it floats on white and glares on dark. Brand yellows are therefore usually pulled a little toward orange and slightly desaturated to buy stability. The value shown approximates the published specification.",
    funZh: "黄色的一个物理特点是它的相对亮度极高 —— 同样是 RGB 值都拉满，纯黄的视觉亮度接近纯白的三倍。这就是为什么黄色文字放在白底上几乎读不出来，也是为什么黄色永远需要一层深色描边或者底衬。",
    funEn: "Yellow has an unusually high relative luminance: with all channels at maximum, pure yellow reads at nearly three times the brightness of a saturated blue. That is why yellow text on white is almost unreadable, and why yellow typography almost always needs a dark outline or a backing panel.",
    catZh: "品牌与命名色",
    catEn: "Brand & Named"
