    histZh: "谷歌绿是四色里最平衡的一个，负责「l」。它偏向黄绿多一点，不像森林绿那样沉，也不像薄荷绿那样轻。品牌四色体系里，绿通常承担「成功 / 可用」的信号，所以明度要跟红黄差不多，否则四个色在并排时会出现重量差。屏幕上的值是官方规格的近似值。",
    histEn: "Google green is the most balanced of the four and carries the L. It leans slightly toward yellow-green, neither as heavy as a forest green nor as light as a mint. Within a four-colour system green usually signals success or availability, so its lightness has to sit close to the red and the yellow or the set acquires an uneven weight. The value shown approximates the published specification.",
    funZh: "把红黄蓝绿四色并排时，最容易出问题的不是色相而是明度。设计师的办法通常是先算四个色的相对亮度，把它们调到同一个区间，再微调色相 —— 顺序反了就会来回返工。",
