    histEn: "Amazon orange comes from the arrow that runs from a to z in the logo, the so-called smile. Its job is practical: on a retail page that is otherwise black type on white, it carries all the emphasis, on buttons, prices and promotions alike. It runs warm and bright so that it holds up on both white and dark grounds. The value shown is an approximation, as Amazon does not use an identical orange across every medium.",
    funZh: "电商强调色有个共同要求：必须在缩略图尺寸下还能被认出来。所以它不能太细、不能太灰，也不能跟红绿这类「折扣 / 库存」信号色撞车 —— 一个橙色背后其实是一整套界面语言。",
    funEn: "Retail accent colours share one requirement: recognisability at thumbnail size. That rules out anything too thin, too grey, or anything that collides with the reds and greens already spoken for by discount and stock signals. Behind a single orange sits a whole interface vocabulary.",
