    histEn: "Microsoft blue is the blue of the four-square logo and has been the base note of the Windows brand for years. It leans cyan, brighter than a true blue and cooler than a sky blue, and it shows up particularly well on dark ground. The four-square logo is itself a statement: a platform broken into four blocks, implying four businesses that stand apart and side by side at once. The value shown is an approximation.",
