    funZh: "有调查说蓝色是全世界被选为「最喜欢的颜色」比例最高的一档，而且跨越文化差异。这个统计结果常被拿来解释为什么蓝在品牌里用得这么泛 —— 它不是最有性格的选择，但是最不容易被讨厌的选择。",
