    histEn: "Pinduoduo red is a warm true red, close to its competitors' and a shade brighter. The convergence of Chinese retail reds is a collective strategy: red has been trained in this market into a reflex meaning you can save money here, and any platform switching away from it would have to educate users from scratch. The value shown is an approximation.",
    funZh: "颜色一旦被市场训练成条件反射，就会变成壁垒：新平台即便做出更好的产品，用别的颜色也要付出额外的认知成本。所以「大家长得像」并不全是缺乏创意，有时是理性选择。",
