    histZh: "壳牌黄是标识上那只贝壳的底色，跟红色描边组成一对。它的明度极高，在加油站这种需要远距离识别、而且常常是夜间照明不足的场景里非常实用。能源行业的标识有个共同要求：必须在高速路边的几秒钟内被认出来，所以配色普遍极端饱和。屏幕上的值是近似值。",
    histEn: "Shell yellow is the ground of the shell emblem, paired with its red outline. Its lightness is very high, which suits petrol stations: they must be recognised at a distance, often under poor night lighting. Energy sector identities share a requirement to be identified from a moving car in a couple of seconds, and their palettes are accordingly saturated to the extreme. The value shown is an approximation.",
    funZh: "加油站标识是「被移动中的人识别」的极端案例，所以它的设计约束跟静态场景完全不同：形状要极简，配色要极饱和，对比要极高。这也解释了为什么成品油品牌的标识普遍比同规模的其他行业更简单。",
    funEn: "Petrol station signage is the extreme case of being recognised by someone in motion, and its constraints differ entirely from static contexts: the shape must be minimal, the colour maximally saturated, the contrast maximal. It also explains why fuel brands generally carry simpler marks than companies of comparable size in other sectors.",
    catZh: "品牌与命名色",
    catEn: "Brand & Named"
