    histZh: "古驰绿是那条经典织带上的绿，跟红一起组成三色条纹。这个绿偏正、明度中等，跟同行业的深色调相比算是相当鲜明。红绿条纹的原型据说来自马肚带，也就是固定马鞍的皮带 —— 一个赛马用具的细节，最后变成了时装史上被仿制最多的图案之一。屏幕上的值是近似值，织物上的绿随材质变化。",
    histEn: "Gucci green is the green of the classic web ribbon, forming a tricolour stripe with red. It is a true green at moderate lightness, notably vivid beside the deep tones common in the sector. The red-green stripe is said to derive from the girth strap that holds a saddle in place — a detail of horse tack that became one of the most imitated patterns in fashion history. The value shown is an approximation; on real fabric the colour shifts with the material.",
    funZh: "品牌图案的法律保护比图形商标弱得多，所以这类条纹是时装史上被抄袭最严重的元素之一 —— 它太简单，改动一两条线的宽度就能声称不同。于是保护的重点转向了「让消费者认得出」，而不是禁止别人用。",
    funEn: "Patterns are far harder to protect legally than graphical marks, which is what made this stripe one of the most copied elements in fashion history: it is simple enough that shifting a single line's width supports a claim of difference. Protection therefore shifted toward making sure consumers recognise it rather than preventing others from using it.",
