    histZh: "巴宝莉米是那张经典格纹里占面积最大的驼色底，搭配黑、白、红三色细线。它明度高、饱和度低，属于最容易跟肤色和环境融在一起的色 —— 这既是它的优势（好搭、耐用、不显脏），也是它的麻烦：太容易被抄袭者换个深浅就绕过去。屏幕上的值是近似值，面料上的米色随材质和光线变化很大。",
    histEn: "Burberry beige is the camel ground occupying most of the classic check, lined with black, white and red. High in lightness and low in saturation, it is among the colours most willing to blend with skin and surroundings — an advantage, since it is easy to wear and forgiving of dirt, and a nuisance, since a copier can shift the shade slightly and claim a different colour. The value shown is an approximation; on fabric the beige varies widely with material and light.",
    funZh: "低饱和的米色系在奢侈品里地位特殊：它不靠抢眼来标识身份，反而靠「看不出想被注意」来表达身份。所以这类品牌很少用高饱和主色，红色只作为细线出现在格纹里。",
    funEn: "Low-saturation beiges have a peculiar standing in luxury: identity is asserted not by being conspicuous but by appearing not to seek attention. Such brands accordingly avoid saturated primaries and let red appear only as a thin line inside a pattern.",
