    histZh: "卡地亚红是那个标志性红色首饰盒的颜色，偏正、不带橙。珠宝行业用红盒的传统跟中国和印度的婚嫁色有关 —— 红在东亚和南亚都指向喜庆，而珠宝的核心市场正在那里。一个颜色，同时是品牌资产和文化策略。屏幕上的值是近似值。",
    histEn: "Cartier red is the colour of the signature jewellery box: true, without orange. The tradition of red boxes in jewellery connects to wedding colour in China and India, where red signals festivity and where much of the market for high jewellery sits. One colour serving simultaneously as brand asset and cultural strategy. The value shown is an approximation.",
    funZh: "那只红盒子的二手价格本身就能说明问题：在二手市场上，带原装红盒的珠宝转售价格明显更高。包装在这里不是附属品，而是一张可转让的品牌凭证 —— 上一位买家留下的盒子，替下一位买家做了担保。",
    funEn: "The resale value of the box itself makes the point: on the secondary market, jewellery with its original red box commands a visibly higher price. This is packaging not as an accessory but as a transferable credential.",
