    histZh: "路易威登棕是涂层帆布上那层深浅交错的棕色底，配以浅色的字母和花纹。这个棕偏暖偏土，跟皮革本色接近，所以耐磨、耐脏、越用越有痕迹 —— 而这恰恰是当初选用它的理由：十九世纪的旅行箱要在火车和轮船上被拖来拖去，颜色太浅就是自找麻烦。屏幕上的值是近似值。",
    histEn: "Louis Vuitton brown is the alternating brown ground of the coated canvas, carrying the pale monogram. Warm and earthy, close to undyed leather, it wears well, hides marks, and improves with use — which was precisely the reason for choosing it: nineteenth-century trunks were dragged on and off trains and ships, and a pale colour would have been asking for trouble. The value shown is an approximation.",
    funZh: "涂层帆布本身就是从实用出发的发明：在帆布上刷一层防水涂料，让箱子既轻又防雨，比皮革便宜也不怕泡水。后来这套工艺变成了奢侈品，但起点是「怎么让行李经得起折腾」。",
    funEn: "Coated canvas was itself a practical invention: a waterproof layer over cloth made a trunk light and rainproof, cheaper than leather and indifferent to being soaked. It later became a luxury, but the starting question was simply how to make luggage survive handling.",
