    histZh: "塔可钟紫是快餐业里罕见的紫，跟粉和黑一起构成了它的整套视觉。快餐配色普遍是红黄暖色，用紫等于主动放弃「食欲色」的加成，换取辨识度 —— 在一片红黄招牌的街角，紫色店面会被最先看到。它也是这套策略最出名的例子。屏幕上的值是近似值。",
    histEn: "Taco Bell purple is a rarity in fast food, and with pink and black it forms the brand's whole visual system. Fast food generally runs warm reds and yellows, so choosing purple means deliberately giving up the appetite-colour advantage in exchange for recognisability: on a corner of red and yellow signs, a purple storefront is the first one noticed. It is the best-known example of that strategy. The value shown is an approximation.",
