    histZh: "红牛蓝是罐身上占面积最大的深蓝，跟银、红组成三色。它偏蓝紫、明度低，跟同为能量饮料常见的荧光色形成了鲜明对比 —— 别人在喊，它在沉。这种「反着做」的配色让它在货架上并不靠亮取胜，而是靠深色块带来的分量感。屏幕上的值是近似值。",
    histEn: "Red Bull blue is the deep blue covering most of the can, forming a tricolour with silver and red. Leaning blue-violet and low in lightness, it stands in sharp contrast to the fluorescent colours common among energy drinks: the others shout, and it sits still. The result is a can that wins on the shelf not by brightness but by the weight a large dark field carries. The value shown is an approximation.",
    funZh: "大面积深色在小尺寸上会糊成一团，但罐装饮料在货架上的最小尺寸仍然足够大，所以这个策略成立。同一套配色搬到手机图标上，深蓝就会吃掉细节 —— 这也是为什么同一个品牌在不同载体上常常要调整配色。",
