    aliasZh: "亨氏红 · Heinz Red",
    aliasEn: "Heinz red",
    histZh: "亨氏红是番茄酱标签上的深红，明度偏低、偏冷，接近熟透番茄皮的颜色。食品标签用深红而非鲜红有实际考虑：鲜红在印刷和货架灯光下容易显得廉价，深红则更像「浓缩、足料」。它也是少数几个颜色跟产品本身强绑定的品牌色之一。屏幕上的值是近似值。",
    histEn: "Heinz red is the deep red of the ketchup label: low in lightness, cool-leaning, close to the skin of a ripe tomato. Food labels favour deep reds over bright ones for a practical reason: bright red tends to look cheap under print conditions and shelf lighting, while a deep red reads as concentrated and generous. It is also one of the few brand colours bound tightly to the product itself. The value shown is an approximation.",
    funZh: "番茄酱的红色其实很依赖品种和成熟度，工业上会靠番茄固形物含量来控制 —— 固形物越高，颜色越深越浓。所以标签上那个深红，某种程度上是在暗示瓶里的浓度。",
    funEn: "The red of ketchup depends heavily on variety and ripeness, and industry controls it largely through solids content: the higher the solids, the deeper and denser the colour. The deep red on the label is, in a sense, advertising the concentration inside.",
