    swZh: "潘通 2024 年度色",
    swEn: "Pantone colour of the year 2024",
    aliasZh: "蜜桃绒 · 柔软的浅桃 · 供应链色",
    aliasEn: "Peach Fuzz · a soft peach · a supply-chain colour",
    histZh: "潘通 2024 年的年度色，一种柔软的浅桃色。同一年，手机和家纺里也集中出现了一批粉色系，这两件事不是巧合 —— 年度色会影响纺织、室内和消费电子的备货。潘通给它的说明里提到了触感和软，也就是说年度色的措辞已经从颜色转向感受 —— 这几年发布的颜色多半配着一套情绪形容词，颜色只是那些形容词的载体。",
    histEn: "Pantone's colour for 2024, a soft pale peach. In the same year a run of pinks appeared across phones and home textiles. The two are not unrelated: a colour of the year feeds into what textiles, interiors and consumer electronics order in advance. Pantone's own wording leaned on touch and softness, meaning the language of a colour of the year has moved from colour to feeling. Recent picks come with a set of mood adjectives attached; the colour is the vehicle for them.",
    funZh: "年度色发布之后的一年里，你会在商场里突然看见大量同一个颜色 —— 因为很多厂的排产是一年前就定好的。颜色是有供应链的。它是典型的「屏幕友好、实物难做」的颜色 —— 桃色在纺织品上非常容易偏灰或者发脏，要染得干净，成本比看起来高得多。",
    funEn: "In the year after a colour of the year is announced you suddenly see a great deal of it in shops, because production runs were fixed twelve months earlier. Colour has a supply chain. It is a textbook screen-friendly, material-hostile colour: peach on textiles greys out or muddies very easily, and producing a clean one costs far more than it looks like it should.",
    catZh: "有故事的色",
    catEn: "Colours with a Story"
