    aliasZh: "佩恩灰 · 佩因灰",
    aliasEn: "Payne's grey",
    histZh: "佩恩灰是十八世纪英国水彩画家威廉·佩恩常用的一种灰，由深蓝、黑和一绺红调成，色相偏蓝而非中性。它后来的名气远超佩恩本人：水彩画里阴影、石头、云层几乎都用它，因为它比纯粹的灰更有空气感，又不像纯黑那样把画面压死。屏幕上的值是近似值。",
    histEn: "Payne's grey is a grey associated with the eighteenth-century English watercolourist William Payne, mixed from a dark blue, black and a touch of red, and therefore blue-leaning rather than neutral. It outgrew its namesake entirely: in watercolour it is used for shadow, stone and cloud almost as a default, because it carries more atmosphere than a plain grey and does not deaden a picture the way pure black does. The value shown is an approximation.",
    funZh: "佩恩灰能流行起来，靠的正是「不是中性灰」这一点。中性灰在画面里会显得死板，因为它不含任何色相倾向，跟周围一切都不发生关系；而偏蓝的灰会自动被读成阴影 —— 这是空气散射留给人的视觉经验。",
    funEn: "What made it popular is precisely that it is not a neutral grey. Neutral greys sit inertly in a picture because they carry no hue and therefore relate to nothing around them, whereas a blue-leaning grey is read automatically as shadow. That reading comes from visual experience with atmospheric scattering.",
