    aliasZh: "胡克绿 · 植物学绿",
    aliasEn: "Hooker's green",
    histZh: "胡克绿得名于十九世纪英国植物学家和插画师威廉·胡克，是普鲁士蓝与藤黄调出的一个深绿，专门用来画叶子。它解决的是植物画里的一个具体问题：天光下的叶片不是一种绿，向阳面和背面差得很远，而单一颜料画不出来，所以需要一个能自由调整的基色。屏幕上的值是近似值。",
    histEn: "Hooker's green is named after the nineteenth-century British botanist and illustrator William Hooker: a deep green mixed from Prussian blue and gamboge, made specifically for painting foliage. It solves a concrete problem in botanical work. A leaf under daylight is not one green — the lit face and the underside differ greatly — and no single pigment supplies both, so what is needed is a base that can be adjusted freely. The value shown is an approximation.",
    funZh: "植物插画至今仍要给新物种留下「模式标本图」，也就是鉴定时依据的那张画。这种图的要求很严格：颜色要随标本状态说明，因为同一种植物在不同季节、不同光照下颜色完全不同 —— 颜色在这里是可复核的证据。",
    funEn: "Botanical illustration still has to produce the type illustration for a new species, the drawing that identification relies on. The requirements are strict, and colour has to be qualified by the state of the specimen, since the same plant differs entirely by season and by light. Colour here is evidence that can be checked.",
    catZh: "有故事的色",
