    histZh: "极致灰是 2021 年潘通双年度色中的一个，色相几乎中性，微偏冷。选一对颜色而不是一个，这在年度色的历史上是第二次 —— 上一次是 2016 年的玫瑰石英配静谧蓝。官方的说法是「两个独立的元素互相支撑」，但更直接的解读是：那一年需要同时表达「稳定」和「希望」。屏幕上的值是近似值。",
    histEn: "Ultimate gray was one half of the Pantone selection for 2021, essentially neutral with a slight cool cast. Choosing a pair rather than a single colour was only the second time the programme had done so, the first being rose quartz with serenity in 2016. The stated reasoning was two independent elements supporting one another, but the simpler reading is that the year required stability and hope to be expressed at once. The value shown is an approximation.",
    funZh: "灰在色彩体系里处境特殊：它既不是色相也不是无彩色，而是饱和度接近零的一段区间。所以「能不能把灰当主色」这件事，几乎每个品牌都会遇到一次，而答案通常跟行业的情绪周期有关。",
    funEn: "Grey occupies an odd position in any colour system: neither a hue nor a non-colour, but the region where saturation approaches zero. Every brand eventually has to decide whether grey can carry a primary role, and the answer usually tracks the emotional cycle of its industry.",
