    histZh: "亮丽黄是 2021 年潘通双年度色里的另一个，明度极高、饱和中等，接近正午的阳光黄。它跟极致灰配在一起，逻辑很清楚：灰提供分量，黄提供温度。这两个色放在一起时，灰会显得更冷，黄会显得更暖 —— 对比会同时加强双方。屏幕上的值是近似值。",
    histEn: "Illuminating was the other half of the 2021 pairing: very high in lightness, moderately saturated, close to noon sunlight. Its logic against the grey is clear — the grey supplies weight and the yellow supplies warmth. Side by side, the grey reads cooler and the yellow warmer; the contrast intensifies both. The value shown is an approximation.",
    funZh: "「对比加强双方」是色彩同时对比的经典现象：把同一个灰放在黄旁边和放在蓝旁边，测出来的观感明度会不一样。这不是错觉，而是视觉系统在做局部归一化的结果。",
