    histEn: "Mocha mousse was the 2025 selection: a warm brown with a pink cast, mid-range in lightness and low in saturation. In traditional vocabularies this is the territory of earth, coffee and leather, a comfortable middle tone. The programme's shift from high saturation toward muted warm neutrals has been widely read as consumer mood moving from expression toward restraint. The value shown is an approximation.",
    funZh: "低饱和的暖褐在商业上有现实优势：它跟绝大多数肤色、木色和金属都不冲突，所以特别好卖。代价是它不出镜 —— 一个用在包装上不会出错，但也不会被记住的颜色。",
    funEn: "Muted warm browns have a practical commercial advantage: they conflict with almost no skin tone, wood or metal, and therefore sell easily. The cost is that they never steal a scene — a colour that cannot go wrong on packaging and will not be remembered either.",
