    histZh: "卡其来自乌尔都语和印地语里的「khākī」，字面意思就是「土色的」。十九世纪中期英属印度军队把白色制服染成土黄，因为白衣服在战场上太显眼 —— 一次纯实用的改装，最后变成了全世界军服和工装的基础色。屏幕上的卡其是近似值，实际军服的卡其从鼠灰到土黄跨度极大。",
    histEn: "Khaki comes from khākī in Urdu and Hindi, literally meaning dusty or earth-coloured. In the mid-nineteenth century the British Indian Army dyed its white uniforms an earth yellow because white was dangerously conspicuous in the field. A purely practical modification ended up supplying the base colour of military and work clothing worldwide. The value shown is an approximation; real service khaki ranges from mouse grey to earth yellow.",
    funZh: "把制服染成土色这件事在当时的军事逻辑上是革命性的：在此之前，军服的思路是「越醒目越能震慑对手」，卡其之后变成了「越看不见越能活下来」。颜色的意义被武器射程直接改写了。",
    funEn: "Dyeing uniforms earth-coloured was a revolution in military logic. Before it, the reasoning ran that the more conspicuous the uniform the more it overawed the enemy; afterwards it became the less you are seen the more likely you survive. Weapons range rewrote the meaning of a colour directly.",
