    histZh: "牛津蓝是牛津大学的校色，是一种很深的正蓝，明度低到接近黑。它跟剑桥的浅蓝形成对照，而这两所学校的赛艇对抗赛正是靠颜色区分的 —— 「浅蓝对深蓝」在英语里干脆成了一句俗语。校色在这里的作用很原始：在一群穿同样衣服的人里，一眼分出敌我。屏幕上的值是近似值。",
    histEn: "Oxford blue is the university's colour: a very dark true blue, low enough in lightness to sit near black. It contrasts with Cambridge's pale blue, and the two universities' boat race is distinguished by exactly that — light blue against dark blue became a stock phrase in English. The job of a varsity colour is elementary here: to tell friend from rival at a glance among people wearing identical clothing. The value shown is an approximation.",
    funZh: "牛津和剑桥的浅蓝色之争有个流传很久的说法，说剑桥最初用的是浅蓝，后来因为褪色被嘲笑，索性就把褪色版的蓝定成了正式校色。这个故事缺乏可靠的文献支持，但它能流传下来，说明大家愿意相信「失误变传统」这种事。",
    funEn: "A long-circulating story holds that Cambridge originally used a blue that faded, was mocked for it, and adopted the faded version as its official colour. Reliable documentation is lacking, but the tale survives because people are willing to believe that an accident can become a tradition.",
