    histZh: "剑桥蓝是一种带灰的浅蓝绿，严格说更接近浅青。它是剑桥大学各运动队的代表色，跟牛津的深蓝正好构成一对。这种「浅对深」的配对在体育里很实用：在赛艇这种远距离、快速掠过的场景里，明度的差别比色相的差别更容易被瞬间识别。屏幕上的值是近似值。",
    histEn: "Cambridge blue is a greyed pale blue-green, strictly closer to a light cyan. It represents the university's sports teams and forms a deliberate pair with Oxford's dark blue. The light-against-dark pairing is practical in sport: in rowing, where the boats pass at speed and at distance, a difference in lightness is registered instantly where a difference in hue is not. The value shown is an approximation.",
    funZh: "远距离识别颜色时，明度比色相重要得多 —— 因为色觉依赖的视锥细胞在视野边缘分布稀少，而明暗感知覆盖整个视野。所以赛艇、球衣、信号旗的配色几乎都以明度差为第一原则。",
    funEn: "At distance, lightness matters far more than hue, because the cone cells that support colour vision are sparse in peripheral vision while brightness is perceived across the whole field. Racing colours, jerseys and signal flags are therefore built on lightness contrast first.",
