    histEn: "Peridot green is the colour of the gem: a bright yellow-leaning green. The stone was called the gem of the sun in ancient Egypt, and Cleopatra is said to have collected it. Mineralogically peridot is one member of the olivine group, and olivine is abundant in the mantle — a great deal of the green in the earth is attributable to it. The value shown approximates a typical stone.",
    funZh: "橄榄石有个特点：它几乎只在一个色相里出现，从黄绿到偏橄榄的绿，不会像别的宝石那样有红有蓝。原因是它致色的铁离子在晶体结构里的位置固定，能变化的范围很窄 —— 一颗宝石的颜色，被矿物结构锁死了。",
    funEn: "Peridot occurs in essentially one hue family, from yellow-green to olive, and does not range across the spectrum the way some gems do. The reason is that the iron responsible for its colour occupies a fixed site in the crystal structure, leaving very little room to vary. The colour is locked in by structure.",
