    histEn: "Amethyst is violet quartz, coloured by iron impurities in the lattice. In antiquity it ranked as a precious stone, since only a few sources produced deep violet crystals; once large South American deposits were found, the price collapsed and it moved from precious to commonplace. A single stone whose standing was rewritten by supply. The value shown is an approximation.",
    funZh: "紫水晶的紫色对光和热都不太稳定：长期暴晒会褪成浅黄或发白，加热到几百度则会变成黄水晶甚至绿水晶 —— 天然紫水晶之所以有深浅之分，一部分就是地质历史里受热程度不同造成的。",
