    histZh: "绿松石是铜铝磷酸盐矿物，颜色从天空蓝到苹果绿都有，取决于成分里铜与铁的比例 —— 铜多偏蓝，铁多偏绿。它在中国、波斯和中美洲都被用了很久，是最早被开采的宝石之一。中文名里的「松」据说来自它常呈松球状的结核形态。屏幕上的值是常见蓝绿色档的近似值。",
    histEn: "Turquoise is a copper aluminium phosphate whose colour runs from sky blue to apple green depending on the ratio of copper to iron in its composition: more copper gives blue, more iron gives green. It was used over a very long period in China, Persia and Mesoamerica and is among the earliest gemstones to be mined. The Chinese name is said to refer to the pine-cone shape the nodules often take. The value shown approximates the common blue-green grade.",
    funZh: "绿松石有个在宝石里罕见的性质：它会「变」。汗液、油脂和化妆品都能渗进它多孔的晶体结构，时间一长颜色就变深变暗。所以一串老珠子跟新珠子放一起，颜色差得很明显 —— 是老化的证据，不是品质问题。",
    funEn: "Turquoise has a property rare among gemstones: it changes. Sweat, oils and cosmetics all penetrate its porous structure, and over time the colour deepens and dulls. An old strand of beads set beside a new one therefore differs plainly — evidence of ageing rather than a defect.",
