    histEn: "Topaz in Chinese is a mineral name for a fluorine-bearing aluminium silicate, but most of what the jewellery trade sells under it has been treated: naturally coloured stones are expensive, while colourless material can be turned blue by heating or irradiation. A large share of blue topaz on the market is therefore a made colour, not a found one. The value shown approximates the natural yellow variety.",
    funZh: "黄玉的「改名」是中国珠宝市场的一个常见混淆点：矿物学上的黄玉（托帕石）和黄玉髓、黄水晶经常被混着叫。真正区分它们的办法是看硬度和晶体形态，而不是看颜色 —— 颜色在这个行业里最不可靠。",
