    histZh: "知更鸟蛋蓝取某些鸟蛋壳的蓝绿色。这个颜色在生物学上有个长期未解的问题：蛋壳的色素到底从哪来。直到近年研究才比较明确 —— 是雌鸟在形成蛋壳时把体内的胆绿素转递进去，而胆绿素正是血红素的分解产物。所以蛋的蓝，跟淤青发青是同一类物质。屏幕上的值是近似值。",
    histEn: "Robin's egg blue is the blue-green of certain bird eggshells. Biologically the colour posed a long-standing puzzle about where the pigment came from, and only recent work has established it with reasonable confidence: the female transfers biliverdin, a breakdown product of haem, into the shell as it forms. The blue of an egg and the green of a bruise come from the same family of substances. The value shown is an approximation.",
    funZh: "蓝色的蛋壳为什么会进化出来，目前主要有两种解释：一是蓝色蛋壳能挡住部分紫外线，保护里面的胚胎；二是它像一种「健康证明」—— 能产出足够胆绿素的雌鸟状态更好，蛋的颜色就成了给雄鸟看的信号。",
    funEn: "Two main explanations compete for why blue eggshells evolved: that the blue screens some ultraviolet and protects the embryo, or that the shell acts as a certificate of health, since a female able to produce plenty of biliverdin is in better condition, making the colour a signal to males.",
