    histEn: "Salmon is the colour of the fish's flesh: a pink leaning orange, fairly light. There is an easily missed fact behind it. The orange-red of wild salmon comes from astaxanthin in the small crustaceans it eats, so the colour is eaten rather than made; farmed salmon fed no added astaxanthin has greyish flesh. What is on the supermarket tray is essentially decided by the recipe. The value shown is an approximation.",
    funZh: "养殖鲑鱼的粉红色是行业里公开的事情，通常会在饲料里加虾青素，还会用色卡来定级 —— 一片鱼排属于哪一档，靠比对标准色卡决定，跟收成水果时看糖度是同一套思路。",
    funEn: "The pinkness of farmed salmon is openly acknowledged in the industry, with astaxanthin added to the feed and the resulting fillets graded by comparison against a colour chart. Which tier a piece belongs to is settled by holding it against a standard, much as sugar content settles a fruit harvest.",
