    histEn: "Avocado green is the colour of the fruit's skin: a dark yellow-green. It has a particular place in design history, having been used across appliances and kitchenware in the 1970s, then dismissed along with the decade for several generations and treated as a synonym for out-of-date. In the last decade it has come back into interiors and fashion — the same value chosen twice by the times, for entirely different reasons. The value shown is an approximation.",
    funZh: "颜色的「过时」往往不是审美判断，而是联想问题：鳄梨绿之所以被嫌弃，是因为它绑定了具体的一批产品和装修风格。等那批东西从生活里消失、只剩照片之后，这个颜色就重新变得中立了。",
    funEn: "A colour going out of fashion is usually about association rather than aesthetics. Avocado green was disliked because it was bound to a specific generation of products and interiors. Once those left daily life and survived only in photographs, the colour became neutral again.",
