    histZh: "南瓜橙取南瓜果肉和果皮的颜色，是高饱和的暖橙。南瓜原产美洲，传入中国之后迅速推广，明代的文献里已经有记载，后来还成了荒年顶饱的作物。它在英语世界里几乎等同于万圣节，在中文里则更多跟秋天和丰收连在一起 —— 同一个色相，两套完全不同的文化剧本。屏幕上的值是近似值。",
    histEn: "Pumpkin orange is the colour of the flesh and rind: a highly saturated warm orange. The squash is native to the Americas and spread rapidly after reaching China, appearing in Ming records and later becoming a crop that carried people through bad harvests. In English-speaking countries it is practically a synonym for Halloween; in Chinese it connects more with autumn and harvest. One hue, two entirely different cultural scripts. The value shown is an approximation.",
    funZh: "南瓜的橙色来自类胡萝卜素，跟胡萝卜、番茄是同一类色素。这类色素是脂溶性的，所以吃南瓜时如果同时摄入油脂，吸收率会明显提高 —— 营养学上「同一锅菜怎么搭」确实有区别。",
    funEn: "Pumpkin's orange comes from carotenoids, the same family of pigments as carrots and tomatoes. They are fat-soluble, so eating squash alongside some fat measurably improves absorption. What else is in the pot genuinely matters nutritionally.",
