    histEn: "Eggplant is a common colour word in English for a dark, muted purple, and Chinese has a matching term belonging to the vegetable branch of its vocabulary. The colour is neither bright nor fresh and sits low in lightness, which suits it to large areas of dark cloth and furniture. Worth noting that the two Chinese renderings are used interchangeably and describe the same family. The value shown is an approximation.",
    funZh: "茄子皮的紫色来自花青素里的翠雀素，同样对酸碱敏感：细胞液偏酸时偏红，偏碱时偏蓝。所以同一颗茄子，不同部位的颜色能差出一小档，切开之后接触空气还会继续变化。",
