    histEn: "Pearl white is the ground tone of a pearl's surface: a warm milky white rather than a pure one. The colour arises from alternating thin layers of calcium carbonate and organic material, making it a structural colour like moonstone, which is why it always carries a soft glow that shifts with the angle. The whiteness of a real pearl is never an even field. The value shown approximates a common variety.",
    funZh: "珍珠层是贝类一层层分泌出来的，每层厚度不到一微米，一年可能只长出零点几毫米。所以一颗大珠需要很多年，而它表面的那种柔光，本质上是一摞极薄的透明层对光反复反射的结果。",
    funEn: "Nacre is secreted layer by layer, each under a micron thick, accumulating perhaps a fraction of a millimetre in a year. A large pearl therefore takes many years, and its soft lustre is at bottom the result of light bouncing repeatedly through a stack of very thin translucent sheets.",
