    histEn: "Lobster red is the vivid orange-red a crustacean takes on after cooking. A live lobster is usually dark blue-brown or dull green, and the change comes down to a pigment-protein complex: astaxanthin is normally bound to a protein that masks its colour, and heat denatures the protein, freeing the pigment so the red shows. The colour is the result of a protein coming apart. The value shown is an approximation.",
    funZh: "虾青素本身是红色的，在活体里被蛋白质「包」着才显不出颜色。同一套机制在虾、蟹、磷虾身上都有，也是为什么煮虾的水会变红 —— 溶出来的那部分色素已经脱离了蛋白质的保护。",
    funEn: "Astaxanthin is red on its own; in living tissue it is masked by the protein it binds. The same arrangement appears in shrimp, crabs and krill, and it is why the water a shrimp boils in goes red: the colour that leaches out has already been released from its protein.",
