    histEn: "Titian red is named after the red hair that recurs throughout the Venetian painter's work: a warm, orange-leaning red. It detached from the paintings and became a standing term in Western usage for hair of a coppery cast, in art and in life alike. A colour fixed by one painter's preference and then moving from painting into ordinary language is uncommon. The value shown is an approximation.",
    funZh: "提香晚年的用色发生了明显变化，红褐用得更多、笔触也更松。艺术史上对原因有不止一种解释，其中包括他年龄增长之后视力的变化 —— 但这类推断缺乏直接证据，只能算一种可能。",
    funEn: "Titian's palette shifted markedly late in life, with more red-browns and looser handling. More than one explanation has been offered, among them changes in his eyesight with age, though such inferences lack direct evidence and remain only plausible.",
