    histEn: "Kelly green is a bright, vivid true green whose name is not fully accounted for; the common explanation traces it to an Irish surname, the colour being widely used in Ireland and among Irish communities. It became a standard choice for American sports teams and school uniforms in the mid-twentieth century and, alongside shamrock green, forms one of the two versions of Irish green. The value shown is an approximation.",
    funZh: "「爱尔兰绿」其实是两个色：凯利绿偏亮偏黄，三叶草绿偏深偏冷。圣帕特里克节的游行队伍里两种都能看到，而官方场合用的多是偏深的那一种 —— 同一面国旗的颜色，在不同的实物上并不统一。",
