    histEn: "Hunter green is a deep yellow-green, said to come from English country hunting dress, where it blends into woodland without resembling military camouflage closely enough to cause confusion. It was widely adopted by schools, clubs and companies in the mid-twentieth century: dark enough to read as formal, not so dark as to look heavy on white. The value shown is an approximation.",
    funZh: "打猎穿绿色这个传统有个实际问题：绿在林地里的伪装效果其实一般，倒是能让同行的猎人互相看见、避免误伤。所以猎装色的功能一半是隐蔽，一半是「让队友认出你」。",
