    aliasEn: "Rose quartz",
    histZh: "玫瑰石英是 2016 年潘通双年度色里的粉色一半，是一种极浅的粉，明度极高、饱和极低。它跟静谧蓝配成一对，官方说法是「性别界限的模糊」。这种极浅的粉在儿童产品和家居里长期占位，但它同时也是最容易被评价为「没性格」的一档颜色。屏幕上的值是近似值。",
    histEn: "Rose quartz was the pink half of the 2016 Pantone pairing: an extremely light pink, very high in lightness and very low in saturation. It was paired with serenity, and the stated reasoning was a blurring of gender boundaries. This kind of pale pink has long occupied children's products and interiors, and it is also the shade most easily dismissed as characterless. The value shown is an approximation.",
    funZh: "极浅的颜色有一个实际的优势：它们的面积可以做得很大而不压迫。所以室内、包装、界面底色的浅色往往比鲜艳色更耐看 —— 代价是单独使用时几乎没有存在感。",
    funEn: "Very light colours have a practical advantage: they can occupy a large area without pressing on the eye. That is why interiors, packaging and interface grounds favour pale colours for durability of effect, at the cost of almost no presence when used alone.",
