    histZh: "静谧蓝是 2016 年潘通双年度色里的蓝色一半，是一种带灰的浅蓝，明度偏高。它跟玫瑰石英的明度非常接近，这正是双色搭配成不成立的关键 —— 两个色如果明度差太多，放在一起就会一个抢一个。灰调的蓝在这里起了稳定作用。屏幕上的值是近似值。",
    histEn: "Serenity was the blue half of the 2016 pairing: a greyed pale blue at fairly high lightness. Its lightness sits very close to rose quartz's, which is exactly what makes a two-colour pairing work — if the two differ much in lightness one will dominate the other. The grey in the blue steadies the combination. The value shown is an approximation.",
    funZh: "双色搭配比单色难得多，因为要同时满足两个条件：明度接近才不会失衡，色相有距离才不会糊成一块。静谧蓝和玫瑰石英基本算是一份标准答案 —— 明度几乎同档，色相正好隔开。",
