    histZh: "探戈橘是 2012 年的潘通年度色，是高饱和的暖橙红。这个色公布的时候正赶上经济刚从危机里缓过来，官方的说明用了「振奋」「活力」这类词。它是年度色里偏激进的一档 —— 明度高、饱和高，用在服装和包装上很跳，但大面积使用会累。屏幕上的值是近似值。",
    histEn: "Tangerine tango was the 2012 selection: a highly saturated warm orange-red. It was announced as the economy was emerging from crisis, and the official language invoked energy and uplift. It is one of the more aggressive choices the programme has made — high in lightness and saturation, striking on clothing and packaging, tiring over a large area. The value shown is an approximation.",
    funZh: "高饱和的暖色有个共同的用法限制：适合做强调，不适合做底。所以这类年度色通常出现在配饰、包装和宣传物料上，很少真的被大面积刷进家里 —— 流行色的落地方式，往往跟它宣传时展示的样子不一样。",
    funEn: "Highly saturated warms share a practical limit: they work as accents and fail as grounds. Such colours of the year therefore turn up on accessories, packaging and campaign material and rarely get painted across a room. How a trend colour is finally used rarely resembles how it was presented.",
