    histZh: "翠玉绿是 2013 年的潘通年度色，是偏青的深绿，饱和中高。它在宝石里对应的是祖母绿，在色彩上更接近青绿之间偏绿的位置。选它的时候，奢侈品和珠宝市场正在恢复，这个绿恰好也带着一层「贵重」的联想 —— 年度色跟产业周期之间的关系，往往比跟审美潮流更紧。屏幕上的值是近似值。",
    histEn: "Emerald was the 2013 selection: a deep green leaning cyan, moderately to highly saturated. It corresponds to the gemstone in name and sits toward the green end of the blue-green band. Luxury and jewellery markets were recovering when it was announced, and the colour carries an association with value — the colour of the year usually tracks industry cycles more closely than it tracks aesthetics. The value shown is an approximation.",
    funZh: "「翠玉绿」和「翡翠色」在中文里都指向宝石，但一个是潘通色号、一个是传统色名，两个体系的取色方法完全不同：一个靠印刷标准，一个靠实物目测。名字撞车不代表数值接近。",
    funEn: "The two Chinese names both point at the gemstone, but one is a Pantone specification and the other a traditional colour word, and the two systems derive colour in entirely different ways: one from print standards, the other from looking at an object. Sharing a name implies nothing about the numbers.",
