    histEn: "Truffle is the colour of the fungus: a greyed dark brown, low in lightness. Truffles carry high status and a high price in cooking, so the name gets borrowed in product naming to imply a tier — truffle leather, truffle packaging — which is to say what is being sold is the association. Borrowing an object's price rather than its hue is a common move in colour naming. The value shown is an approximation.",
