    histEn: "Mulberry names the vivid purple-red of crushed berries, more saturated than the skin itself. In English the word also covers a purple-red dyed cloth, and its relation to Chinese mulberry culture is one of species rather than use: China treated the tree as the foundation of sericulture, while Europe treated it more as a fruit tree. One colour name, two entirely different production contexts. The value shown is an approximation.",
    funZh: "桑葚压碎后颜色比果皮更浓，是因为花青素集中在细胞液里，破壁之后才大量释放。所以同一个水果有两种颜色：完整时偏暗偏青，碾碎时鲜亮。取名的人各取一半，才有了这个色名的含糊。",
    funEn: "A crushed mulberry is more intense than the skin because the anthocyanins sit in the cell sap and are only released in quantity once the cells are broken. One fruit therefore offers two colours — darker and bluer intact, vivid when crushed — and the name draws on both, which is where its vagueness comes from.",
