    histEn: "Latte is milk with espresso: a warm pale brown. Over the last two decades it has become a popular colour for interiors and clothing for a practical reason — it conflicts with white walls, timber floors and beige sofas alike, making it the default safe choice in a renovation. Once a colour becomes safe it acquires both ubiquity and the label of having no personality. The value shown is an approximation.",
