    histEn: "Slate grey is the colour of slate: a grey with a blue cast, one of the cooler greys. Slate is a metamorphic rock that splits along its bedding into thin sheets, which is why it served historically as roofing and as writing tablets — English still says a clean slate, after the stone. Behind a colour word there is often a history of a material. The value shown is an approximation.",
    funZh: "板岩之所以能劈成片，是因为它承受过定向压力，矿物重新排列成了平行的层。所以它「有方向」：顺着层理一敲就开，垂直方向却很难断 —— 材料的性格直接决定了它能被用来做什么。",
    funEn: "Slate splits because it was subjected to directed pressure that realigned its minerals into parallel layers. It therefore has a grain: struck along the bedding it comes apart, across it, it resists. The character of the material decides what it can be used for.",
