    histEn: "Tomato is a bright red with orange in it, high in lightness. The plant is native to South America and was grown as an ornamental in Europe for a long time after arriving in the sixteenth century, suspicion of poison being widespread — the stems and leaves do in fact contain small amounts of alkaloids, though the fruit does not. It was late to be accepted in China as well, only becoming a staple of home cooking in recent times. The value shown is an approximation.",
    funZh: "番茄的红色来自番茄红素，是类胡萝卜素里的一种。它跟胡萝卜素不同的是更偏红、抗氧化能力更强。而且番茄红素是脂溶性的，加热加一点油之后吸收率会明显上升 —— 番茄炒蛋其实是个很合理的搭配。",
    funEn: "The red comes from lycopene, a carotenoid that leans redder than carotene and is a stronger antioxidant. It is fat-soluble, and heating it with a little oil raises absorption appreciably — which makes a tomato-and-egg stir-fry a chemically sensible combination.",
