    histEn: "Glacier blue is the blue of ice: pale, greyish, cyan-leaning. The reason ice is blue is related to the sky but not the same. Dense ice absorbs red light more strongly, so what survives a certain thickness leans blue. Thicker ice is therefore bluer and thin ice is nearly white — one substance whose colour depends on how much of it you are looking through. The value shown is an approximation.",
    funZh: "冰的蓝不来自任何色素，而是来自吸收本身。这一点跟天空的散射蓝、孔雀羽毛的结构蓝都不同：同样是「物体显得蓝」，背后的机制却可以有三种完全不同的物理原因。",
    funEn: "The blue of ice comes from no pigment at all but from absorption itself. That makes it distinct both from the scattering that blues the sky and from the structural colour of a peacock feather. Three entirely different physical mechanisms, all producing the statement that an object looks blue.",
