    histZh: "沙色取细沙的颜色，是极浅的暖米，明度高、饱和低。它的命名逻辑很直接 —— 拿最不缺的实物当参照。有意思的是，沙的颜色其实绝大部分来自石英颗粒，而杂质决定了它偏黄还是偏粉：含铁多的偏红，含贝壳碎屑多的偏白。屏幕上的值是近似值。",
    histEn: "Sand colour is fine sand: an extremely pale warm beige, high in lightness and low in saturation. The naming logic is direct, taking the most abundant available object as its reference. Interestingly, most of the colour comes from quartz grains, and the impurities decide whether it leans yellow or pink: iron makes it redder, shell fragments make it paler. The value shown is an approximation.",
    funZh: "不同海滩的沙颜色差得很远，从白到黑都有 —— 黑色的沙滩来自火山玄武岩碎屑，粉色的来自有孔虫壳。所以「沙色」这个色名其实是在用一个词覆盖一整个色阶，比多数色名都含糊。",
    funEn: "Sand varies enormously from beach to beach, white through black. Black sand comes from volcanic basalt fragments, pink from foraminiferan shells. The colour word therefore covers an entire range with a single term, more loosely than most.",
